    def start_rf_scan(self, technology, radio, capture_type, antenna, antenna_panel=None, local_cell=None, timeout=60):
        """
        Starts RF Scan
        :param technology: configured technology, "WCDMA", "LTE FDD", "LTE TDD", "NR FDD", "NR TDD" can be used.
        :type technology: str
        :param radio: radio used for RF Scan, i.e. "RMOD-1 (AQQN)"
        :type radio: str
        :param capture_type: capture type, "Composite Rx (HBF0)", "Carrier Rx (FIR9)" can be used.
        :type capture_type: str
        :param antenna: antenna i.e. "PHYANT 1", "ANT 2"
        :type antenna: str
        :param antenna_panel: antenna panel i.e. "PHYANT-1 Full Array"
        :type antenna_panel: str
        :param local_cell: full name of local cell i.e. "NRCELL-1"
        :type local_cell: str
        :param timeout: timeout
        :type timeout: int
        :return: path to downloaded file or test failed notice
        :rtype: str
        """
        return self._api.start_rf_scan(technology=technology, radio=radio, capture_type=capture_type,
                                       antenna=antenna, antenna_panel=antenna_panel, local_cell=local_cell,
                                       timeout=timeout)

